/* Основной контейнер секции */
.priceSection {
  padding: 64px 0;
  background-color: #121212;
  width: 100%;
  max-width: 1040px;
  margin: 0 auto;
  font-family: inherit;
}

/* Шапка блока с линиями по бокам (копия стиля Галереи) */
.headerRow {
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 48px;
  width: 100%;
}

.title {
  font-size: 32px;
  font-weight: 500;
  color: #ffffff;
  padding: 0 24px;
  letter-spacing: 1px;
}

.line {
  flex-grow: 1;
  height: 1px;
  background: rgba(255, 255, 255, 0.1);
}

/* Горизонтальное меню переключения вкладок */
.tabsMenu {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 40px;
  width: 100%;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  padding-bottom: 16px;
}

.tabButton {
  background: none;
  border: none;
  font-size: 16px;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.4);
  cursor: pointer;
  padding: 8px 4px;
  letter-spacing: 0.5px;
  transition: color 0.2s ease, transform 0.2s ease;
  position: relative;
}

.tabButton:hover {
  color: rgba(255, 255, 255, 0.8);
}

/* Активное состояние вкладки с подчеркиванием */
.activeTab {
  color: #ffffff;
}

.activeTab::after {
  content: "";
  position: absolute;
  bottom: -17px; /* Сажаем линию точно на нижнюю рамку меню */
  left: 0;
  width: 100%;
  height: 2px;
  background-color: #ffffff;
}

/* Контейнер для таблицы */
.tableContainer {
  width: 100%;
  overflow-x: auto; /* Защита от вылетания на мобилках */
}

/* Стилизация самой таблицы */
.priceTable {
  width: 100%;
  border-collapse: collapse; /* Схлопываем двойные рамки */
  text-align: left;
}

/* Строка таблицы с линией-разделителем */
.tableRow {
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  transition: background-color 0.2s ease;
}

.tableRow:hover {
  background-color: rgba(255, 255, 255, 0.02); /* Легкий интерактивный блик */
}

/* Общие стили для ячеек */
.tableRow td {
  padding: 20px 0;
  font-size: 16px;
  color: #ffffff;
}

/* Наименование работы (прижимаем влево) */
.itemName {
  font-weight: 400;
  width: 70%; /* Занимает большую часть строки */
}

/* Единица измерения (по центру) */
.itemUnit {
  font-weight: 300;
  color: rgba(255, 255, 255, 0.5);
  width: 10%;
  text-align: center;
}

/* Цена (выравниваем по правому краю) */
.itemPrice {
  font-weight: 500;
  width: 20%;
  text-align: right;
  white-space: nowrap; /* Чтобы "руб." не улетало на новую строку */
}
